<template>
  <el-container class="tutor-page">
    <el-header class="app-header"><AsideVue/></el-header>
    <el-main class="tutor-main">
      <div class="workspace-bar">
        <div>
          <div class="workspace-title"><el-icon><Reading/></el-icon>DeepTutor 智能学习助手</div>
          <div class="workspace-subtitle">知识问答、深度解题与引导式学习</div>
        </div>
        <div class="workspace-actions">
          <el-tag :type="running ? 'success' : (starting ? 'warning' : 'info')" effect="light">
            {{ running ? '服务已连接' : (starting ? '正在启动' : '服务未启动') }}
          </el-tag>
          <el-button v-if="running" @click="reload"><el-icon><Refresh/></el-icon>刷新</el-button>
          <el-button v-if="running" @click="openStandalone"><el-icon><TopRight/></el-icon>独立窗口</el-button>
          <el-button type="primary" :loading="starting" @click="running ? reload() : start()">
            {{ running ? '重新载入' : '启动 DeepTutor' }}
          </el-button>
        </div>
      </div>

      <div v-if="running" class="tutor-frame-wrap">
        <iframe :key="frameKey" :src="tutorUrl" class="tutor-frame" title="DeepTutor 智能学习助手"
          allow="clipboard-read; clipboard-write; microphone"/>
      </div>

      <div v-else class="empty-state">
        <div class="brand-orb"><el-icon :size="52"><Reading/></el-icon></div>
        <h2>把复杂问题拆成可理解的学习路径</h2>
        <p>DeepTutor 服务独立运行，但会在当前系统的统一导航和工作区中呈现。</p>
        <div class="feature-grid">
          <div v-for="item in features" :key="item.title" class="feature-item">
            <el-icon :size="28" :color="item.color"><component :is="item.icon"/></el-icon>
            <div><strong>{{ item.title }}</strong><span>{{ item.description }}</span></div>
          </div>
        </div>
        <el-button type="primary" size="large" :loading="starting" @click="start">启动并进入 DeepTutor</el-button>
        <el-alert v-if="error" class="error-alert" :title="error" type="error" :closable="false" show-icon/>
      </div>
    </el-main>
  </el-container>
</template>

<script>
import axios from 'axios'
import AsideVue from '@/components/AsideVue.vue'
import { Reading, Refresh, TopRight } from '@element-plus/icons-vue'

export default {
  name: 'DeepTutor', components: { AsideVue, Reading, Refresh, TopRight },
  data: () => ({
    running: false, starting: false, error: '', frameKey: 0, tutorUrl: '/deeptutor', pollTimer: null,
    features: [
      {icon:'ChatDotSquare',color:'#2f80ed',title:'智能问答',description:'围绕课程知识连续追问'},
      {icon:'EditPen',color:'#16a085',title:'深度解题',description:'拆解步骤并解释推理过程'},
      {icon:'Collection',color:'#8e6ad8',title:'学习沉淀',description:'管理会话、资料与知识库'}
    ]
  }),
  created() { this.check() },
  beforeUnmount() { if (this.pollTimer) clearTimeout(this.pollTimer) },
  methods: {
    async check() {
      try {
        const {data} = await axios.get('/api/isDeepTutorRunning')
        this.running = Boolean(data.running)
        this.starting = data.status === 'starting'
        this.error = data.error || ''
        this.tutorUrl = '/deeptutor'
        return this.running
      } catch (e) { this.running=false; return false }
    },
    async start() {
      this.starting=true; this.error=''
      try {
        const {data} = await axios.post('/api/startDeepTutor')
        this.tutorUrl='/deeptutor'
        await this.poll(0)
      } catch (e) {
        this.starting=false
        this.error=e.response?.data?.error || 'DeepTutor 启动失败，请检查路径和依赖配置。'
      }
    },
    async poll(attempt) {
      if(await this.check()) { this.starting=false; this.$message.success('DeepTutor 已接入'); return }
      if(attempt>=45) { this.starting=false; this.error=this.error || 'DeepTutor 启动超时，请查看后端日志。'; return }
      this.pollTimer=setTimeout(()=>this.poll(attempt+1),2000)
    },
    reload() { this.frameKey += 1 },
    openStandalone() { window.open(this.tutorUrl,'_blank','noopener') }
  }
}
</script>

